      for (const c of this.claimsOf(p.id).filter(countsWithHolds(p.holds, this.todayNow()))) {
        const period = periodOn(periods, c.date);
        if (period) live.set(period.id, (live.get(period.id) ?? 0) + (this.claimDue(p, c, dueTerms) ?? 0));
      }"""
